// Proactive English C1 · Syria Edition · Book 2 · Unit 20 — Answer Key
const L = require('./lib');
const { p, h1, h2, pb, sp, box, table, C } = L;
const out = [];
const S = (t) => p(t, { bold: true, color: C.teal, before: 160, after: 60 });
const A = (t) => p(t, { indent: 200, after: 50 });
const SAMPLE = (paras) => box('Sample answer', paras, 'FFFFFF', C.navy);
const NOTE = (t) => box('Note', [t], C.lyellow, C.orange);

out.push(h1('Unit 20  Refusing Without Giving Grounds for Appeal — Answer Key'));
out.push(p('_Proactive English · C1 · Book 2 · Syria Edition · Answer Key_', { color: '7F7F7F' }));
out.push(box('How to use this key', [
  '**The peer review is at band 4 throughout and does not change again, so the rate of refusals is now a measurement and not an accident.** ⚠ **The reviewer writes the one sentence they would put in the writer\'s place, and the writer says whether it is theirs.** **In Unit 19 four of ten supplied sentences were refused and the key treated that as the correct rate; expect the same here, and expect two of the refusals to be about tone, which is the weakest ground and should be said so.** **A class in which nothing is refused has not understood the band** — **and a class in which the writer argues the refusal rather than stating it has not understood that a refusal needs no grounds, which is also the subject of the unit.**',
  '**The unit\'s own discipline is mechanical and this key marks it mechanically.** ⚠ **One test applied: if the obstacle were removed tomorrow, would the answer be yes?** **One reason, unremovable, with no second reason and no _in any case_.** **An alternative with a date, a figure and a name — or the sentence that there is none.** **A condition the applicant cannot manufacture, or nothing.** **A first paragraph that states the reader\'s purpose with no _but_ anywhere near it.** **Every one of those is checkable in about ten seconds and none is a matter of judgement.**',
  '**One thing in this unit is a matter of judgement and the key says so each time it arises.** ⚠ **Whether a refusal is kind.** **The unit refuses to answer it and substitutes a question that can be answered: what will the reader do on Monday?** **Do not let the room settle the first question** — **and when a student says that the honest version is cruel, ask what the applicant does in the fortnight after each of the two letters, and let the room count the weeks.**',
], C.lblue, C.navy));

// ===================== 20.1 =====================
out.push(pb());
out.push(h2('20.1  Not able, or not willing'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. ⚠ **The refusal read aloud exactly, and then what the student did — not what they felt.** **Seven of ten had done something to remove an obstacle and four of the seven later found the obstacle was not the reason** — **and the board wants the ten refusals in one column and the ten actions in the other, because the two columns together are the whole cycle and no explanation is needed.**'));
out.push(A('**b** Decisions said as decisions: **2** and **4**. ⚠ **Each names who decided and what was decided, and points at the reason.** **1, 3 and 5 are a decision in the clothes of an incapacity** — _unable_, _resources do not permit_, _not possible_ — **and the room should be asked what each of the three instructs the reader to do, which is to find resources, find a way, or wait.**'));
out.push(NOTE('⚠ **The cycle depends on one question and the question has to be asked out loud, of the room, before anybody writes anything.** **If the obstacle were removed tomorrow, would the answer be yes?** **Eight of ten first sentences in this class said _unable_ and six of the eight failed that test, and all six writers said, when asked, that they had known.** **That last fact is the cycle** — **the fault is not ignorance and it cannot be repaired by explanation, because every one of them already knew.** ⚠ **So do not explain it.** **Put the question on the board, have each student apply it to their own first sentence, and let the six discover the answer in their own handwriting.**'));
out.push(NOTE('⚠ **Protect the five.** **_Unable_ is true in about one refusal in five and a room that has just discovered the fault will start calling every incapacity a lie.** **The round closed on the first and the file is dated the second: that is _unable_, the obstacle is a date, and the honest letter names it.** **A board with no power to waive a residence condition is _unable_** — **and a room that cannot find the genuine cases has learnt a slogan and not a test.** ⚠ **Run row 2 and row 4 of both practice cards before the pair work and let the class hear two refusals that are correct as written.**'));
out.push(S('Language box · Practise'));
out.push(A('**1** _The committee has decided not to fund it._ ⚠ **Money existed and you chose elsewhere: a decision, said flat.**   **2** _The round closed on 1 March and your file is dated the second._ **A genuine obstacle, named.**   **3** ⚠ **The monthly representative: _we have decided not to stock it this year_** — **and he stops the week he is told.**   **4** _We are unable to assist_ → **_we have decided not to._**   **5** ⚠ _I am sorry that this has taken five weeks_ — **an apology for a delay you caused, at the end, and the only apology in the letter.**'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**Row 1** **Not willing.** **Next: he finds a co-funder and comes back.** ⚠ **Should have been: _we have decided not to fund it, and the reason is below._**',
  '**Row 2** ⚠ **Genuinely not able.** **The obstacle is a date and it is nameable.** **Next: he applies in the next round.** **Correct as written.**',
  '**Row 3** **Not willing, dressed as a capacity.** ⚠ **_Resources do not permit_ when the committee had money is the exact fault of the unit** — **next: he halves the budget, which is eleven weeks of somebody\'s work.**',
  '**Row 4** ⚠ **Genuinely not able: the board has no power.** **Next: nothing is available, which the letter should say in those words.** **Correct as written.**',
  '**Row 5** **The hardest.** ⚠ **A decision in the passive: _it is not possible_ removes the person who decided** — **next: he asks what would make it possible, and nobody can answer him, which is what makes the letter appealable.** **Should have been: _I am not going to run it._**',
]));
out.push(S('Stage 3 · Practise (sample – Card B)'));
out.push(SAMPLE([
  '**Row 1** **Not willing.** ⚠ **_On this occasion_ implies a next occasion and there is not one.**',
  '**Row 2** ⚠ **Not able, and the obstacle is a power rather than a date, which the room will treat as the same thing.** **It is not: a date passes and a power does not.**',
  '**Row 3** **Not willing.** **Next: he reduces the figure.** ⚠ **And the reduction will not help, because the figure was never the reason.**',
  '**Row 4** ⚠ **Not able, and embarrassing to the body, which is 20.2 arriving a cycle early** — **and if the room notices that, say that it is the next cycle and do not take it further.**',
  '**Row 5** **A decision in the passive again, and this is the fourth passive of ten on the two cards** — ⚠ **which is about the real rate in refusals and should be said.**',
]));
out.push(S('Stage 3R · Perform – listener task'));
out.push(A('**Rows 2 and 4 on both cards are genuinely _not able_ and the room must say so rather than hunt** — **a date and a power, and the honest letter names which.** ⚠ **Rows 5 are the hardest**: both are decisions in the passive, **and the room will want to keep the passive because it removes the person who decided.** **Say what that costs: a letter with nobody in it cannot be answered, and a letter that cannot be answered is appealed.**'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**My first sentence.** _We regret that we are unable to support your application at this time._',
  '**The test.** **If the obstacle were removed tomorrow, would the answer be yes?** ⚠ **No.** **There was no obstacle: we had the money and we funded two other applications.**',
  '**Rewritten.** _The committee has decided not to support the application, and the reason is in the second paragraph._',
  '**b** ⚠ **My partner read only the first sentence and said she would halve the budget and come back in March.** **And the harder question: what did I actually want her to do?** **Nothing** — **and no refusal of mine has ever said so.**',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Mrs Rizk has written twenty-seven refusals this year and counted the first words of each of them last month, and twenty-four begin with some form of we are unable, and of those twenty-four, nineteen were decisions. Mrs Khoury repeated the figure, and Mrs Rizk said the committee had money, the scheme was eligible, and they chose other schemes, which is a decision, and she wrote unable because unable is kinder to write and she had never once thought about what it is like to receive. Mr Attar asked what it is like to receive, and Mrs Khoury said it is an instruction to remove an obstacle, and that is the whole cycle: unable tells the applicant that something is in the way, so they go and move it, and they come back, and the obstacle is gone, and you must either say yes or admit that it was never the reason. Mrs Oueidat asked what that costs them, and six weeks in the case Mrs Rizk knows best, and the co-funder\'s goodwill, which they spent on her committee: they came back in March with a letter from the governorate that had taken them five visits, and the committee refused it again for the same reason. Dr Qabbani said so decided not to is the honest one, and Mrs Khoury said it is the honest one and it is not comfortable, and the room should notice which of those two facts is doing the work, because decided not to invites an argument about judgement, which is personal and has no end and is the argument you are entitled to receive. Mr Shihabi asked whether unable is ever right, and five of the twenty-seven, and the test is one question: if the obstacle were removed tomorrow, would the answer be yes. Mr Tayara asked about the tone, and Mrs Oueidat said flat, and said once. Mrs Tarabishi asked whether you may say you are sorry at all, and once, at the end, for a thing you have actually done to them. Mrs Ajouz said hers is a representative who comes back every month, and then he has been told unable at some point and he is removing obstacles. And Mrs Rizk said the thing she will take away is the five visits, and that when she refused him the second time he wrote back and asked, quite politely, what the real reason had been the first time. And Mrs Khoury said the repair is in the opening itself: the committee has decided not to fund it where it was a decision, with we are unable kept for the five where an obstacle can be named, and the obstacle named in the same sentence.']));
out.push(A('⚠ **Two things in the report are the teaching and both are at the end.** **The five visits, which are the cost of one sentence written in four minutes** — **and the four-line letter asking what the real reason had been, which is the only form of complaint this fault ever produces, because the applicant cannot know what he is complaining about.** **Ask the room who has received a letter like that and not recognised it.**'));
out.push(S('Board clinic – typical mistakes'));
out.push(A('**1** ⚠ **_Unable_ where money existed** → **eight of ten, and six failed the test.**   **2** **The decision in the passive** → **nobody decided, so nobody can be answered.**   **3** ⚠ **Regret in the first sentence** → **read as the opening of a negotiation.**   **4** **_At this time_ and _on this occasion_** → **a next occasion is implied and there is none.**   **5** ⚠ **Two apologies** → **one, at the end, for something you did.**   **6** **The genuine incapacity rewritten as a decision** → **rows 2 and 4; the test runs both ways.**'));
out.push(S('Board – the ten refusals, the kind, and what the reader does next'));
out.push(A('⚠ **Run this at 20.1 Stage 1a with the ten refusals on the board and the last two columns empty.** **The room fills them out loud, one line at a time, and nobody fills the row for their own letter.** **The right-hand column is the whole cycle** — **and the three genuine incapacities in it are what stop the class learning that every refusal is a lie.**'));
out.push(table(['THE REFUSAL AS SENT', 'ABLE, OR WILLING?', 'WHAT THE READER DOES NEXT'], [
  ['_We are unable to assist on this occasion._', '⚠ **A decision**', '**Removes an obstacle that is not there**'],
  ['_The round closed on 1 March._', '**Not able**', '**Applies next round**'],
  ['_Our resources do not permit us._', '⚠ **A decision**', '**Halves the budget**'],
  ['_The board has no power to waive the condition._', '**Not able**', '**Nothing: and the letter should say so**'],
  ['_It is not possible to take this forward._', '⚠ **A decision, in the passive**', '**Asks what would make it possible**'],
  ['_We have decided not to fund it._', '**A decision, said so**', '**Argues about the choice**'],
  ['_We shall keep your details on file._', '⚠ **A decision, concealed**', '**Waits, for nothing**'],
  ['_The post was filled on 4 March._', '**Not able**', '**Looks elsewhere**'],
  ['_We are not carrying a second piece this quarter._', '**A decision, said so**', '**Offers another subject**'],
  ['_We would be glad to see a revised proposal._', '⚠ **A decision, with work attached**', '**Spends eleven weeks**'],
], [3, 2, 2]));
out.push(S('Stage 5 · Read'));
out.push(A('**1** ⚠ **It came back in March with a letter from the governorate that had taken five visits, a co-funder nobody had heard of, and a budget cut by a fifth** — **and the committee refused it again for the reason it had refused it the first time, which was the two schemes already funded in that district.**'));
out.push(A('**2** ⚠ **It asked what the real reason had been the first time.** **She had no answer she was willing to put in writing** — **and she treats that unwillingness as the answer, which is the only diagnostic in the note and the room should be shown that it is available to anybody.**'));
out.push(A('**3** ⚠ **Three applicants have written since September to say that the committee chose wrongly.** **The arguments are about the choice, which was the real ground all along** — **and her letters had been concealing it, so the arguments she now receives are the arguments she ought to have been receiving for nine years.**'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**H. RIZK** · _note on twenty-seven refusals_ · **4 November**',
  '**What I counted.** **The first eight words of every refusal I wrote this year.** ⚠ **Twenty-four of twenty-seven begin with some form of _we are unable_.** **Of those, nineteen were decisions.**',
  '**Why I wrote _unable_.** **Because it is kinder to write.** ⚠ **Not kinder to read, which I had never thought about.**',
  '**What _unable_ tells the reader.** **That something is in the way, so they go and move it.**',
]));
out.push(S('Stage 7 · Write freely (sample, 281 words)'));
out.push(SAMPLE([
  '**T. SHIHABI** · _note on a year of commissioning refusals_ · _ninety-one pitches, one desk_ · **12 November**',
  '**What I counted.** **The first sentence of every refusal I sent to a freelance this year.** ⚠ **Ninety-one refusals; sixty-eight of them say some version of _we do not have space_.** **Of the sixty-eight, fifty-one were sent in weeks when I commissioned something else.**',
  '**Why I wrote it.** **Because _no space_ is a fact about a page and nobody argues with a page.** ⚠ **It is also, in fifty-one cases, untrue in the only sense that matters: there was space and I gave it to a piece I preferred.**',
  '**What it tells the reader.** **To come back when there is space.** ⚠ **Nine writers came back within the month with the same piece, two of them three times** — **and one woman re-pitched a feature on the inspectorate five times across eleven months, improving it each time, and the reason I was never going to run it was that I do not think she can carry a piece of that length.**',
  '**The letter that made me count.** **Four lines from her in October, asking whether the problem was the subject.** ⚠ **It was not the subject and I had never said it was** — **and I had never said what it was either, which left her improving the only thing my letters had mentioned.**',
  '**The test.** **If the space existed tomorrow, would I run it?** **No.** ⚠ **Then the refusal is a decision about her and I owe her the decision, not the page.**',
  '**What it costs.** **An argument about judgement, which I shall sometimes lose.** **I have had two since I changed the sentence and one of them was right.**',
  '**And the thing I had not expected.** **She has not pitched since.** ⚠ **I do not know whether that is the system working.**',
]));
out.push(S('Stage 7P · Respond (sample slip — band 4, with the writer\'s answer)'));
out.push(SAMPLE([
  '**THE SLIP, unsigned.** **Reader: the freelance in the last paragraph.** **Absent: what she should do instead.** **Criterion — the line copied:** _"I do not think she can carry a piece of that length."_ ⚠ **The note says the decision is owed to her and does not say the one thing she could act on, which is that a shorter commission is available.**',
  '**THE SENTENCE I WOULD PUT IN YOUR PLACE.** ⚠ _I have told her that I shall not commission a feature from her and that I shall commission eight hundred words whenever she brings me a subject of this kind._',
  '**THE WRITER\'S ANSWER.** ⚠ _It is mine and I had been avoiding writing it, because it is the sentence that ends the eleven months properly._ **Accepted, and it goes in the note and in the letter.**',
  '**A second slip, unsigned.** **Reader: another commissioning editor reading the note.** **Absent: the two arguments the writer lost or won.**',
  '**THE SENTENCE I WOULD PUT IN YOUR PLACE.** _Both arguments were uncomfortable and I would rather have had neither._',
  '**THE WRITER\'S ANSWER.** ⚠ _Refused: it is about my comfort, which is the subject the whole note is trying to get out of the way._ **One of the two arguments was right, and that sentence went in instead.**',
]));
out.push(S('Stage 7R · Share'));
out.push(A('⚠ **Two counts and then the band.** **How many first sentences said _unable_, or its equivalent?** **Eight of ten, and six of the eight failed the test, and all six writers knew.** **Then: how many students have removed an obstacle in response to a refusal?** **Seven, and four later found the obstacle was not the reason.** ⚠ **Then the band: how many supplied sentences were refused?** **Four of ten is the right rate** — **and say that a refusal is a legitimate answer and needs no grounds, which is the unit arriving in its own classroom procedure.**'));

// ===================== 20.2 =====================
out.push(pb());
out.push(h2('20.2  The reason that is also a limit'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. ⚠ **The reason, and then how an applicant would remove it.** **Nine of ten reasons in this class could be removed and six of the nine had already been removed by somebody** — **and the second figure is the one to write on the board, because it is the cycle: the removal is not hypothetical, it has already happened, six times, to these ten people.**'));
out.push(A('**b** Cannot be met by a better application: **2** and **4**. ⚠ **A district already funded twice, and a schedule revised before the institution existed.** **1, 3 and 5 are faults in an application** — **a budget, an ownership demonstration and a level of detail, all three improvable, and all three therefore an instruction.**'));
out.push(NOTE('⚠ **The commonest failure of this cycle is the mixed letter and it is worth more board time than the unremovable reason itself.** **A letter that gives an unremovable reason and then lists three improvable faults has told the applicant to improve an application that cannot be funded** — **and four of ten refusals in this class did exactly that.** **The writers are not confused: they are being thorough, and thoroughness is the fault.** ⚠ **Mark it with one question: which sentence in this letter does the reader act on?** **If two sentences compete, the improvable one wins, because it is the only one they can do anything about** — **and the room can see that in its own letters in under a minute.**'));
out.push(NOTE('⚠ **The embarrassing reason is the test of whether the room has understood the unit, and one student in ten will produce it.** **_The schedule was last revised before your institution existed._** **Read that one aloud and stay with it.** **The alternative sentence — _your qualification does not meet the schedule_ — is true, is what most bodies write, and moves an institutional failure on to an applicant, which is the one thing a refusal must never do.** ⚠ **Then say what goes where: the reason goes in the letter, and the fact that the schedule is twelve years old goes up to whoever maintains it, which is 18.7 and is a different document.** **A class that leaves this cycle thinking the embarrassing reason may be omitted has learnt the opposite of the unit.**'));
out.push(S('Language box · Practise'));
out.push(A('**1** _The budget is too high_ → ⚠ _the programme does not fund a scheme above forty thousand in this round._   **2** _The detail is insufficient_ → **an instruction, not a reason: _the proposal gives no maintenance interval._**   **3** _No evidence of ownership_ → ⚠ **usually an instruction; unremovable only where the schedule itself excludes the applicant.**   **4** _Too long_ → **_we are not carrying a second piece on this subject this quarter._**   **5** ⚠ **The embarrassing one, in the letter and not in the note.**'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**Row 1** ⚠ **Unremovable version: _the programme does not fund a scheme above forty thousand in this round._** **A figure and a round, which the applicant cannot argue with and can plan around.**',
  '**Row 2** ⚠ **No unremovable reason behind it.** **The fault is real and in the application** — **so the honest document is the instruction: _the proposal gives no maintenance interval; with one it would be competitive in the autumn round._**',
  '**Row 3** **Unremovable: _the programme funds works only on premises held under a lease of five years or more._** ⚠ **And if that is not true, there is no unremovable reason and the room must say so.**',
  '**Row 4** ⚠ **The embarrassing one.** **_The schedule was last revised in 2013, before your institution was founded._** **In the letter.** **And a note to whoever maintains the schedule, which is a separate document and is 18.7.**',
  '**Row 5** **The hardest.** ⚠ **_Too long_ is almost never the reason** — **the unremovable version is about the commission: _we are not running a second piece on this subject this quarter._** **The room will try to keep the length.**',
]));
out.push(S('Stage 3 · Practise (sample – Card B)'));
out.push(SAMPLE([
  '**Row 1** **Unremovable: _the commission was placed with a staff writer before your pitch arrived._** ⚠ **A date and a person, and nothing the pitch can do about either.**',
  '**Row 2** ⚠ **No unremovable reason.** **A piece with one source is a fault in the piece** — **and the instruction is _a second source on the figure in paragraph 3 and I shall run it._**',
  '**Row 3** **Unremovable where the timetable is set by somebody else: _the governorate publishes the figures in April and the round closes in March._** ⚠ **The room should notice that this is a date and not a judgement.**',
  '**Row 4** ⚠ **Embarrassing to the body: the form on the website was the superseded version until July.** **The letter says so.** **_You used the wrong form_ is the sentence that must not be sent.**',
  '**Row 5** **No experience in the sector is a fact about the applicant and not about the application** — ⚠ **and it is unremovable in the cruellest way, because nothing they do this year will change it.** **If it is the reason, it is the reason, and the letter says it once.**',
]));
out.push(S('Stage 3R · Perform – listener task'));
out.push(A('**Rows 2 and 4 on both cards have no unremovable reason behind them** — **two are genuine faults, where the honest document is an instruction, and two are embarrassing to the body, where the letter must say so.** ⚠ **Rows 5 are the hardest**: both can be made unremovable by naming the commission or the programme, **and the room will try to keep them as faults in the applicant, which is the move the whole cycle exists to stop.**'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**The reason as I wrote it.** _The application was not sufficiently detailed._ ⚠ **Removable, and he removed it: eleven pages in place of four.**',
  '**The unremovable reason behind it.** **The directorate has approved two posts of this kind this year and will not approve a third before April.**',
  '**Is it true?** ⚠ **Yes, and I knew it when I wrote the first letter.**',
  '**b** ⚠ **My partner tried to remove it and could not.** **Then she asked whether it was true, and the harder half: whether anybody above me would be embarrassed by it in writing.** **They would** — **and it still goes in the letter, which took me the length of the pair work to accept.**',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Mrs Rizk sorted her reasons into two kinds last week, removable and unremovable, and the proportion is not what she expected: nine of her ten standing reasons are removable, which are the budget, the detail, the evidence of ownership and the timetable, and all four of those are faults in an application and not facts about the world. Ms Huda asked what a removable reason gets you, and Mrs Khoury said the same application, improved, and a second refusal to write, which is not a theory but arithmetic: you have told somebody what is wrong, they have fixed it, and you have either to fund it or to produce a reason you did not give the first time, and the second reason, arriving second, reads as something you have gone looking for. Mr Attar asked what an unremovable reason looks like, and that the programme has funded two schemes in this district this year and does not fund a third, which nothing in the application can change, and the applicant can act on it. Dr Qabbani said so the unremovable reason is kinder, and Mrs Oueidat said it is more useful and it is not kinder, and the room should not be allowed to blur those, because an unremovable reason closes a door and a closed door is a loss, while a removable reason leaves it open and costs six weeks of walking towards it. Mrs Tarabishi asked what happens if the only true reason is removable, and then you say so and you say what to change, which is a different letter and a shorter one. Mrs Khoury said the two documents must not be mixed, and four of ten refusals in the class did exactly that. Mr Shihabi said his was a piece turned down for being too long, and removable, and he will cut it. Mr Tayara asked what happens if the unremovable reason is embarrassing to the organisation, and Mrs Oueidat said it usually is, and that is why it is in the internal note instead of the letter. And Mrs Rizk said two applicants have argued with an unremovable reason and both arguments were good: one showed that the second scheme was in a different sub-district and was funded, and the other showed that the programme had funded three in a district in 2022, which nobody at the committee had remembered. And Dr Qabbani asked what happens if the reason is a decision and not a rule at all, and Mrs Rizk said the decision is then the reason and it is unremovable in the only sense that matters, because nothing the applicant does will change a choice that has already been made, and the choice and the constraint go into one sentence.']));
out.push(A('⚠ **The two arguments at the end are not a warning against the method and the room will take them as one.** **An unremovable reason, when it is wrong, is wrong in public and has to be withdrawn** — **and both of these were withdrawn, and both applicants were right.** **Ask the room what the alternative is: a removable reason is never wrong in public, because nobody can check it, which is exactly why it is worse.**'));
out.push(S('Board clinic – typical mistakes'));
out.push(A('**1** ⚠ **The mixed letter** → **four of ten; which sentence does the reader act on?**   **2** **The embarrassing reason moved to the internal note** → **the letter is where it belongs.**   **3** ⚠ **_Your qualification does not meet the schedule_** → **an institutional failure moved on to an applicant.**   **4** **A removable reason called unremovable** → **the partner removes it in a minute.**   **5** ⚠ **Both documents in one letter** → **a refusal with a reason, or a refusal with an instruction.**   **6** **The unremovable reason asserted and not checked** → **two in this class were wrong.**'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** ⚠ **He cut the budget by a fifth, obtained a letter from the governorate in five visits, and found a co-funder** — **eleven weeks of work by three people, in response to sentences she had written in about four minutes.** **The ratio is the argument of the note and should be read out as a ratio.**'));
out.push(A('**2** ⚠ **Because it is true, it costs the programme nothing, and it is the only sentence in the letter the applicant can use with his own board.** **She left it out for nine years because it felt like softening a refusal** — **and it is not softening: it is a separate fact, which is the distinction the cycle turns on.**'));
out.push(A('**3** ⚠ **That the district rule was written in 2019 for a different funding level and nobody has revised it.** **It is embarrassing to the programme, it is not the applicant\'s business, and it goes up to the secretariat in a different document** — **which is 18.7 and should be named as such, because the class wrote that document six units ago.**'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**The letter of March, as I wrote it.** _We are unable to approve the post at this time. The job description lacks detail and the business case does not quantify the saving._ ⚠ **Two removable faults and no reason.**',
  '**What the applicant did.** **Eleven pages in place of four, with a costing.** ⚠ **Three weeks of a head of department\'s time.**',
  '**The letter of October, as I now write it.** _The directorate has decided not to approve the post. Two posts of this kind have been approved this year and a third will not be approved before April._',
  '**What is not in the October letter.** ⚠ **The job description and the business case, both of which are better than they were and neither of which was the reason.**',
]));
